import java.util.regex.*;

public class Main {
    public static void main(String[] args) {

        // Try extracting all hashtags from a social media post!
        String post = "Loving #Java and #RegEx! Also exploring #Streams and #Lambda in #Java21";

        Pattern hashtagPattern = Pattern.compile("#(\\w+)");
        Matcher m = hashtagPattern.matcher(post);

        System.out.println("Hashtags found:");
        while (m.find()) {
            System.out.println("  #" + m.group(1) + "  at index " + m.start());
        }

        // Try validating an Indian PIN code
        String[] pins = {"110001", "99999", "560001", "01234"};
        for (String pin : pins) {
            System.out.println(pin + " valid PIN: " + pin.matches("[1-9][0-9]{5}"));
        }
    }
}

